        // On the first call to nonReentrant, _status will be NOT_ENTERED
        if (_status == ENTERED) {
            revert ReentrancyGuardReentrantCall();
        }

        // Any calls to nonReentrant after this point will fail
        _status = ENTERED;
    }

    function _nonReentrantAfter() private {
        // By storing the original value once again, a refund is triggered (see
        // https://eips.ethereum.org/EIPS/eip-2200)
        _status = NOT_ENTERED;
    }

    /**
     * @dev Returns true if the reentrancy guard is currently set to "entered", which indicates there is a
     * `nonReentrant` function in the call stack.
     */
    function _reentrancyGuardEntered() internal view returns (bool) {
        return _status == ENTERED;
    }
}

contracts/DAppToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title DAppToken
 * @dev Standardized ERC-20 token for dApps with fixed allocation
 * @notice Allocation: 80% Use-to-mint, 10% Liquidity, 5% Treasury, 3% Dev, 2% Airdrops
 */
contract DAppToken is ERC20, Ownable, ReentrancyGuard {
    // Fixed total supply (e.g., 1M tokens)
    uint256 public immutable MAX_SUPPLY;
    
    // Allocation percentages (basis points, 10000 = 100%)
    uint256 public constant USE_TO_MINT_PERCENTAGE = 8000; // 80%
    uint256 public constant LIQUIDITY_PERCENTAGE = 1000;   // 10%
    uint256 public constant TREASURY_PERCENTAGE = 500;     // 5%
    uint256 public constant DEV_PERCENTAGE = 300;          // 3%
    uint256 public constant AIRDROP_PERCENTAGE = 200;      // 2%
    
    // Allocation addresses
    address public rewardVault;      // 80% - Use-to-mint rewards
    address public liquidityReserve; // 10% - Locked until DEX
    address public treasury;         // 5% - Kasparex + Project
    address public devAddress;       // 3% - Dev/maintenance
    address public airdropAddress;   // 2% - Airdrops & bonuses
    
    // Minting control
    address public minter; // RewardManager or ProofOfUtility contract
    bool public mintingEnabled = true;
    bool public burnEnabled = false;
    
    // Events
    event MinterUpdated(address indexed oldMinter, address indexed newMinter);
    event MintingToggled(bool enabled);
    event BurnToggled(bool enabled);
    event AllocationDistributed(
        address rewardVault,
        address liquidityReserve,
        address treasury,
        address devAddress,
        address airdropAddress
    );
    
    /**
     * @dev Constructor sets up token with fixed supply and allocation
     * @param _name Token name
     * @param _symbol Token symbol
     * @param _maxSupply Maximum supply (e.g., 1_000_000 * 10^18)
     * @param _rewardVault Address for use-to-mint rewards
     * @param _liquidityReserve Address for liquidity reserve
     * @param _treasury Address for treasury
     * @param _devAddress Address for dev/maintenance
     * @param _airdropAddress Address for airdrops
     */
    constructor(
        string memory _name,
        string memory _symbol,
        uint256 _maxSupply,
        address _rewardVault,
        address _liquidityReserve,
        address _treasury,
        address _devAddress,
        address _airdropAddress
    ) ERC20(_name, _symbol) Ownable(msg.sender) {
        require(_maxSupply > 0, "DAppToken: Invalid max supply");
        require(_rewardVault != address(0), "DAppToken: Invalid reward vault");
        require(_liquidityReserve != address(0), "DAppToken: Invalid liquidity reserve");
        require(_treasury != address(0), "DAppToken: Invalid treasury");
        require(_devAddress != address(0), "DAppToken: Invalid dev address");
        require(_airdropAddress != address(0), "DAppToken: Invalid airdrop address");
        
        MAX_SUPPLY = _maxSupply;
        rewardVault = _rewardVault;
        liquidityReserve = _liquidityReserve;
        treasury = _treasury;
        devAddress = _devAddress;
        airdropAddress = _airdropAddress;
        
        // Distribute initial allocation
        _distributeAllocation();
    }
    
    /**
     * @dev Distribute tokens according to allocation percentages
     */
    function _distributeAllocation() internal {
        uint256 useToMint = (MAX_SUPPLY * USE_TO_MINT_PERCENTAGE) / 10000;
        uint256 liquidity = (MAX_SUPPLY * LIQUIDITY_PERCENTAGE) / 10000;
        uint256 treasuryAmount = (MAX_SUPPLY * TREASURY_PERCENTAGE) / 10000;
        uint256 devAmount = (MAX_SUPPLY * DEV_PERCENTAGE) / 10000;
        uint256 airdropAmount = MAX_SUPPLY - useToMint - liquidity - treasuryAmount - devAmount; // Remainder for airdrops
        
        _mint(rewardVault, useToMint);
        _mint(liquidityReserve, liquidity);
        _mint(treasury, treasuryAmount);
        _mint(devAddress, devAmount);
        _mint(airdropAddress, airdropAmount);
        
        emit AllocationDistributed(
            rewardVault,
            liquidityReserve,
            treasury,
            devAddress,
            airdropAddress
        );
    }
    
    /**
     * @dev Mint tokens (only by minter)
     * @param to Address to mint to
     * @param amount Amount to mint
     */
    function mint(address to, uint256 amount) external {
        require(msg.sender == minter, "DAppToken: Only minter can mint");
        require(mintingEnabled, "DAppToken: Minting disabled");
        require(totalSupply() + amount <= MAX_SUPPLY, "DAppToken: Exceeds max supply");
        
        _mint(to, amount);
    }
    
    /**
     * @dev Burn tokens (if enabled)
     * @param amount Amount to burn
     */
    function burn(uint256 amount) external {
        require(burnEnabled, "DAppToken: Burning disabled");
        _burn(msg.sender, amount);
    }
    
    /**
     * @dev Set minter address (only owner)
     * @param _minter New minter address
     */
    function setMinter(address _minter) external onlyOwner {
        require(_minter != address(0), "DAppToken: Invalid minter");
        address oldMinter = minter;
        minter = _minter;
        emit MinterUpdated(oldMinter, _minter);
    }
    
    /**
     * @dev Toggle minting (only owner)
     * @param _enabled Whether minting is enabled
     */
    function setMintingEnabled(bool _enabled) external onlyOwner {
        mintingEnabled = _enabled;
        emit MintingToggled(_enabled);
    }
    
    /**
     * @dev Enable burning after full emission (only owner)
     * @param _enabled Whether burning is enabled
     */
    function setBurnEnabled(bool _enabled) external onlyOwner {
        burnEnabled = _enabled;
        emit BurnToggled(_enabled);
    }
    
    /**
     * @dev Get remaining mintable supply
     */
    function getRemainingSupply() external view returns (uint256) {
        return MAX_SUPPLY - totalSupply();
    }
}

contracts/FeeCollector.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./Treasury.sol";

/**
 * @title FeeCollector
 * @dev Interface contract for dApps to send fees to Treasury
 * @notice Provides a simple interface for collecting fees from dApp transactions
 */
contract FeeCollector is Ownable {
    // Treasury contract address
    Treasury public treasury;

    // Events
    event FeeForwarded(address indexed from, uint256 amount, uint256 timestamp);
    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);

    /**
     * @dev Constructor sets the Treasury contract address
     * @param _treasury Address of the Treasury contract
     */
    constructor(address _treasury) Ownable(msg.sender) {
        require(_treasury != address(0), "FeeCollector: Invalid treasury address");
        treasury = Treasury(_treasury);
    }

    /**
     * @dev Forward fees to Treasury
     * @notice This function receives fees and forwards them to the Treasury contract
     */
    function forwardFee() external payable {
        require(msg.value > 0, "FeeCollector: Fee must be greater than 0");
        treasury.collectFee{value: msg.value}();
        emit FeeForwarded(msg.sender, msg.value, block.timestamp);
    }

    /**
     * @dev Update Treasury contract address
     * @param _treasury New Treasury contract address
     */
    function setTreasury(address _treasury) external onlyOwner {
        require(_treasury != address(0), "FeeCollector: Invalid treasury address");
        address oldTreasury = address(treasury);
        treasury = Treasury(_treasury);
        emit TreasuryUpdated(oldTreasury, _treasury);
    }
}

contracts/FeeRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./FeeCollector.sol";
import "./RevenueTreeManager.sol";
import "./RewardManager.sol";
import "./LoyaltyPoints.sol";

/**
 * @title FeeRouter
 * @dev Splits fee (Revenue Tree + FeeCollector), optionally distributes GRID reward and awards points.
 * @notice dApps call forwardFeeAndRevenue(payer) or forwardFeeAndRevenueWithRewards(payer, transactionType).
 */
contract FeeRouter is Ownable {
    uint256 public constant BPS = 10000;

    RevenueTreeManager public revenueTreeManager;
    FeeCollector public feeCollector;
    uint256 public treeBps;

    RewardManager public rewardManager;
    LoyaltyPoints public loyaltyPoints;
    mapping(string => uint256) public baseRewardWei; // transactionType => GRID wei (18 decimals)

    mapping(address => bool) public authorizedDApps;

    event Forwarded(address indexed payer, uint256 total, uint256 toTree, uint256 toTreasury);
    event ForwardedWithRewards(address indexed payer, uint256 total, string transactionType, uint256 rewardWei);
    event TreeBpsUpdated(uint256 oldBps, uint256 newBps);
    event AuthorizedDAppSet(address indexed dapp, bool allowed);
    event RewardManagerSet(address indexed rm);
    event LoyaltyPointsSet(address indexed lp);
    event BaseRewardSet(string transactionType, uint256 amountWei);

    error Unauthorized();
    error InvalidAmount();

    modifier onlyAuthorizedDApp() {
        if (!authorizedDApps[msg.sender]) revert Unauthorized();
        _;
    }

    constructor(
        address _revenueTreeManager,
        address _feeCollector,
        uint256 _treeBps
    ) Ownable(msg.sender) {
        require(_revenueTreeManager != address(0), "FeeRouter: Invalid RevenueTreeManager");
        require(_feeCollector != address(0), "FeeRouter: Invalid FeeCollector");
        require(_treeBps <= BPS, "FeeRouter: treeBps must be <= 10000");
        revenueTreeManager = RevenueTreeManager(payable(_revenueTreeManager));
        feeCollector = FeeCollector(payable(_feeCollector));
        treeBps = _treeBps;
    }

    /**
     * @dev Receive fee and split only (no GRID/points). Same as before.
     */
    function forwardFeeAndRevenue(address payer) external payable onlyAuthorizedDApp {
        if (msg.value == 0) return;
        uint256 toTree = (msg.value * treeBps) / BPS;
        uint256 toTreasury = msg.value - toTree;
        if (toTree > 0) revenueTreeManager.distributeToUpline{value: toTree}(payer);
        if (toTreasury > 0) feeCollector.forwardFee{value: toTreasury}();
        emit Forwarded(payer, msg.value, toTree, toTreasury);
    }

    /**
     * @dev Receive fee, split, then distribute GRID reward and award points. Legacy: no payment amount = fixed reward per tx.
     */
    function forwardFeeAndRevenueWithRewards(address payer, string calldata transactionType) external payable onlyAuthorizedDApp {
        _forwardFeeAndRevenueWithRewards(payer, transactionType, 0);
    }

    /**
     * @dev Receive fee, split, then distribute GRID reward (scaled by paymentAmountWei) and award points (scaled by paymentAmountWei).
     * paymentAmountWei = total payment in wei (e.g. msg.value from SimplePayment). Reward = (paymentAmountWei/1e18) * baseRewardPer1iKAS * tierBps/BPS.
     */
    function forwardFeeAndRevenueWithRewards(address payer, string calldata transactionType, uint256 paymentAmountWei) external payable onlyAuthorizedDApp {
        _forwardFeeAndRevenueWithRewards(payer, transactionType, paymentAmountWei);
    }

    function _forwardFeeAndRevenueWithRewards(address payer, string calldata transactionType, uint256 paymentAmountWei) internal {
        if (msg.value == 0) return;
        uint256 toTree = (msg.value * treeBps) / BPS;
        uint256 toTreasury = msg.value - toTree;
        if (toTree > 0) revenueTreeManager.distributeToUpline{value: toTree}(payer);
        if (toTreasury > 0) feeCollector.forwardFee{value: toTreasury}();

        uint256 baseWei = baseRewardWei[transactionType];
        uint256 rewardWei;
        if (baseWei > 0 && address(rewardManager) != address(0)) {
            uint256 multBps = address(loyaltyPoints) != address(0) ? loyaltyPoints.getTierMultiplierBps(payer) : BPS;
            if (paymentAmountWei > 0) {
                rewardWei = (paymentAmountWei * baseWei / 1e18) * multBps / BPS;
            } else {
                rewardWei = (baseWei * multBps) / BPS;
            }
            if (rewardWei > 0) {
                try rewardManager.distributeRewardDirect(payer, rewardWei) {
                    emit ForwardedWithRewards(payer, msg.value, transactionType, rewardWei);
                } catch {}
            }
        }
        if (address(loyaltyPoints) != address(0)) {
            if (paymentAmountWei > 0) {
                try loyaltyPoints.awardPointsForPayment(payer, transactionType, paymentAmountWei) {} catch {}
            } else {
                try loyaltyPoints.awardPointsWithMultiplier(payer, transactionType) {} catch {}
            }
        }
    }

    function setAuthorizedDApp(address dapp, bool allowed) external onlyOwner {
        authorizedDApps[dapp] = allowed;
        emit AuthorizedDAppSet(dapp, allowed);
    }

    function setTreeBps(uint256 _treeBps) external onlyOwner {
        require(_treeBps <= BPS, "FeeRouter: treeBps must be <= 10000");
        uint256 old = treeBps;
        treeBps = _treeBps;
        emit TreeBpsUpdated(old, _treeBps);
    }

    function setRewardManager(address _rewardManager) external onlyOwner {
        rewardManager = RewardManager(_rewardManager);
        emit RewardManagerSet(_rewardManager);
    }

    function setLoyaltyPoints(address _loyaltyPoints) external onlyOwner {
        loyaltyPoints = LoyaltyPoints(_loyaltyPoints);
        emit LoyaltyPointsSet(_loyaltyPoints);
    }

    function setBaseReward(string calldata transactionType, uint256 amountWei) external onlyOwner {
        baseRewardWei[transactionType] = amountWei;
        emit BaseRewardSet(transactionType, amountWei);
    }

    receive() external payable {}
}

contracts/GRIDToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title GRIDToken
 * @dev GRID token - Global Reward and Incentive Distribution token
 * @notice Fixed max supply (10B GRID), deflationary (burns on conversion/spend)
 */
contract GRIDToken is ERC20, Ownable, ReentrancyGuard {
    // Fixed max supply: 10B GRID
    uint256 public constant MAX_SUPPLY = 10_000_000_000 * 10**18;
    
    // Reward vault for pre-minted tokens
    address public rewardVault;
    
    // Burn tracking
    uint256 public totalBurned;
    
    // Events
    event TokensBurned(address indexed from, uint256 amount);
    event RewardVaultUpdated(address indexed oldVault, address indexed newVault);
    
    /**
     * @dev Constructor pre-mints all tokens to reward vault
     * @param _rewardVault Address to receive pre-minted tokens
     */
    constructor(address _rewardVault) ERC20("GRID Token", "GRID") Ownable(msg.sender) {
        require(_rewardVault != address(0), "GRIDToken: Invalid reward vault");
        rewardVault = _rewardVault;
        
        // Pre-mint all tokens to reward vault
        _mint(_rewardVault, MAX_SUPPLY);
    }
    
    /**
     * @dev Burn tokens (deflationary mechanism)
     * @param amount Amount to burn
     */
    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
        totalBurned += amount;
        emit TokensBurned(msg.sender, amount);
    }
    
    /**
     * @dev Burn tokens from a specific address (for conversions)
     * @param from Address to burn from
     * @param amount Amount to burn
     */
    function burnFrom(address from, uint256 amount) external {
        _spendAllowance(from, msg.sender, amount);
        _burn(from, amount);
        totalBurned += amount;
        emit TokensBurned(from, amount);
    }
    
    /**
     * @dev Update reward vault address (only owner)
     * @param _rewardVault New reward vault address
     */
    function setRewardVault(address _rewardVault) external onlyOwner {
        require(_rewardVault != address(0), "GRIDToken: Invalid reward vault");
        address oldVault = rewardVault;
        rewardVault = _rewardVault;
        emit RewardVaultUpdated(oldVault, _rewardVault);
    }
    
    /**
     * @dev Get circulating supply (total supply - burned)
     */
    function circulatingSupply() external view returns (uint256) {
        return totalSupply() - totalBurned;
    }
    
    /**
     * @dev Get burn percentage of max supply
     */
    function burnPercentage() external view returns (uint256) {
        if (MAX_SUPPLY == 0) return 0;
        return (totalBurned * 10000) / MAX_SUPPLY; // Basis points
    }
}

