contracts/LoyaltyPoints.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title LoyaltyPoints
 * @dev Soulbound participation points. Multiplier from KREX tier (hardcoded thresholds).
 * @notice Only authorized callers (e.g. FeeRouter) can call awardPointsWithMultiplier.
 */
contract LoyaltyPoints is Ownable {
    uint256 public constant BPS = 10000;

    struct LoyaltyData {
        uint256 totalPoints;
        uint256 participationDays;
        uint256 lastActivity;
        uint256 streakDays;
    }

    mapping(address => LoyaltyData) public userLoyalty;
    mapping(string => uint256) public actionPoints;
    mapping(string => uint256) public pointsPer1iKAS; // e.g. "dapp-payment" => 100 XP per 1 iKAS
    uint256 public streakInterval = 86400;

    mapping(address => bool) public authorizedCallers;
    IERC20 public krexToken; // optional: set to read balance for tier multiplier

    // Hardcoded KREX tier thresholds (18 decimals, same as tKREX/KREX)
    uint256 private constant TIER1_MIN = 1 * 10**18;
    uint256 private constant TIER2_MIN = 10_000_000 * 10**18;
    uint256 private constant TIER3_MIN = 50_000_000 * 10**18;
    uint256 private constant TIER4_MIN = 100_000_000 * 10**18;

    event PointsAwarded(address indexed user, string actionType, uint256 points, uint256 totalPoints, uint256 timestamp);
    event StreakUpdated(address indexed user, uint256 streakDays, uint256 timestamp);
    event ActionPointsUpdated(string actionType, uint256 oldPoints, uint256 newPoints);
    event AuthorizedCallerSet(address indexed caller, bool allowed);
    event KREXTokenSet(address indexed token);

    modifier onlyAuthorized() {
        require(authorizedCallers[msg.sender], "LoyaltyPoints: Unauthorized");
        _;
    }

    constructor() Ownable(msg.sender) {
        actionPoints["vote"] = 10;
        actionPoints["proposal"] = 50;
        actionPoints["payment"] = 5;
        actionPoints["dapp-payment"] = 5;
        pointsPer1iKAS["dapp-payment"] = 100;
        actionPoints["product-purchase"] = 10;
        actionPoints["article-creation"] = 20;
        actionPoints["listing"] = 15;
        actionPoints["quiz-completion"] = 25;
        actionPoints["dao-vote"] = 3;
        actionPoints["game-entry"] = 10;
        actionPoints["daily_login"] = 1;
    }

    /**
     * @dev Returns tier multiplier in BPS. Tier0=10000, Tier1=10000, Tier2=20000, Tier3=50000, Tier4=100000.
     */
    function _tierMultiplierBps(address user) internal view returns (uint256) {
        if (address(krexToken) == address(0)) return BPS;
        uint256 bal = krexToken.balanceOf(user);
        if (bal < TIER1_MIN) return BPS;   // Tier0: 1x
        if (bal < TIER2_MIN) return BPS;   // Tier1: 1x
        if (bal < TIER3_MIN) return 20000; // Tier2: 2x
        if (bal < TIER4_MIN) return 50000; // Tier3: 5x
        return 100000;                     // Tier4: 10x
    }

    /**
     * @dev Public view for FeeRouter to apply same multiplier to tGRID rewards.
     */
    function getTierMultiplierBps(address user) external view returns (uint256) {
        return _tierMultiplierBps(user);
    }

    /**
     * @dev Award points scaled by payment amount: points = (paymentAmountWei/1e18) * pointsPer1iKAS[actionType] * tierBps/BPS. Only callable by authorized (e.g. FeeRouter).
     */
    function awardPointsForPayment(address user, string memory actionType, uint256 paymentAmountWei) external onlyAuthorized {
        require(user != address(0), "LoyaltyPoints: Invalid user");
        if (paymentAmountWei == 0) return;
        uint256 perUnit = pointsPer1iKAS[actionType];
        if (perUnit == 0) return;
        uint256 multBps = _tierMultiplierBps(user);
        uint256 points = (paymentAmountWei * perUnit * multBps) / (1e18 * BPS);
        if (points == 0) points = 1;

        LoyaltyData storage loyalty = userLoyalty[user];
        uint256 prevActivity = loyalty.lastActivity;
        loyalty.totalPoints += points;
        loyalty.lastActivity = block.timestamp;

        if (prevActivity > 0 && (block.timestamp - prevActivity) >= streakInterval) {
            loyalty.participationDays++;
            if ((block.timestamp - prevActivity) < 2 * streakInterval) {
                loyalty.streakDays++;
            } else {
                loyalty.streakDays = 1;
            }
            emit StreakUpdated(user, loyalty.streakDays, block.timestamp);
        }

        emit PointsAwarded(user, actionType, points, loyalty.totalPoints, block.timestamp);
    }

    /**
     * @dev Award points with on-chain KREX tier multiplier. Only callable by authorized (e.g. FeeRouter).
     */
    function awardPointsWithMultiplier(address user, string memory actionType) external onlyAuthorized {
        require(user != address(0), "LoyaltyPoints: Invalid user");
        uint256 basePoints = actionPoints[actionType];
        if (basePoints == 0) return;
        uint256 multBps = _tierMultiplierBps(user);
        uint256 points = (basePoints * multBps) / BPS;
        if (points == 0) points = 1;

        LoyaltyData storage loyalty = userLoyalty[user];
        uint256 prevActivity = loyalty.lastActivity;
        loyalty.totalPoints += points;
        loyalty.lastActivity = block.timestamp;

        if (prevActivity > 0 && (block.timestamp - prevActivity) >= streakInterval) {
            loyalty.participationDays++;
            if ((block.timestamp - prevActivity) < 2 * streakInterval) {
                loyalty.streakDays++;
            } else {
                loyalty.streakDays = 1;
            }
            emit StreakUpdated(user, loyalty.streakDays, block.timestamp);
        }

        emit PointsAwarded(user, actionType, points, loyalty.totalPoints, block.timestamp);
    }

    /**
     * @dev Legacy: award base points only. Restricted to owner.
     */
    function awardPoints(address user, string memory actionType) external onlyOwner {
        require(user != address(0), "LoyaltyPoints: Invalid user");
        uint256 points = actionPoints[actionType];
        if (points == 0) return;
        LoyaltyData storage loyalty = userLoyalty[user];
        uint256 prevActivity = loyalty.lastActivity;
        loyalty.totalPoints += points;
        loyalty.lastActivity = block.timestamp;
        if (prevActivity > 0 && (block.timestamp - prevActivity) >= streakInterval) {
            loyalty.participationDays++;
            if ((block.timestamp - prevActivity) < 2 * streakInterval) loyalty.streakDays++;
            else loyalty.streakDays = 1;
            emit StreakUpdated(user, loyalty.streakDays, block.timestamp);
        }
        emit PointsAwarded(user, actionType, points, loyalty.totalPoints, block.timestamp);
    }

    function awardPointsBatch(address[] memory users, string[] memory actionTypes) external onlyOwner {
        require(users.length == actionTypes.length, "LoyaltyPoints: Array length mismatch");
        for (uint256 i = 0; i < users.length; i++) {
            address user = users[i];
            string memory actionType = actionTypes[i];
            if (user == address(0)) continue;
            uint256 points = actionPoints[actionType];
            if (points == 0) continue;
            LoyaltyData storage loyalty = userLoyalty[user];
            loyalty.totalPoints += points;
            loyalty.lastActivity = block.timestamp;
            emit PointsAwarded(user, actionType, points, loyalty.totalPoints, block.timestamp);
        }
    }

    function getUserLoyalty(address user) external view returns (LoyaltyData memory) {
        return userLoyalty[user];
    }

    function getTotalPoints(address user) external view returns (uint256) {
        return userLoyalty[user].totalPoints;
    }

    function getStreak(address user) external view returns (uint256) {
        return userLoyalty[user].streakDays;
    }

    function setActionPoints(string memory actionType, uint256 points) external onlyOwner {
        uint256 oldPoints = actionPoints[actionType];
        actionPoints[actionType] = points;
        emit ActionPointsUpdated(actionType, oldPoints, points);
    }

    function setPointsPer1iKAS(string memory actionType, uint256 points) external onlyOwner {
        pointsPer1iKAS[actionType] = points;
    }

    function setStreakInterval(uint256 _interval) external onlyOwner {
        streakInterval = _interval;
    }

    function setAuthorizedCaller(address caller, bool allowed) external onlyOwner {
        require(caller != address(0), "LoyaltyPoints: Invalid caller");
        authorizedCallers[caller] = allowed;
        emit AuthorizedCallerSet(caller, allowed);
    }

    function setKREXToken(address _krexToken) external onlyOwner {
        krexToken = IERC20(_krexToken);
        emit KREXTokenSet(_krexToken);
    }
}

contracts/ProofOfUtility.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./DAppToken.sol";
import "./GRIDToken.sol";
import "./RewardManager.sol";

/**
 * @title ProofOfUtility
 * @dev Tracks on-chain usage events and mints rewards
 * @notice Gas-efficient P-o-U tracking with batch processing
 */
contract ProofOfUtility is Ownable, ReentrancyGuard {
    // RewardManager contract
    RewardManager public rewardManager;
    
    // Usage event structure
    struct UsageEvent {
        address user;
        address dAppContract;
        uint256 dAppId;
        string actionType; // e.g., "vote", "proposal", "payment"
        uint256 timestamp;
    }
    
    // Track events per user
    mapping(address => UsageEvent[]) public userEvents;
    
    // Track events per dApp
    mapping(address => UsageEvent[]) public dAppEvents;
    
    // Event counter
    uint256 public totalEvents;
    
    // Events
    event UsageEventRecorded(
        address indexed user,
        address indexed dAppContract,
        uint256 indexed dAppId,
        string actionType,
        uint256 timestamp
    );
    event RewardMinted(
        address indexed user,
        address indexed token,
        uint256 amount,
        string rewardType
    );
    event RewardManagerUpdated(address indexed oldManager, address indexed newManager);
    
    /**
     * @dev Constructor
     * @param _rewardManager Address of RewardManager contract
     */
    constructor(address _rewardManager) Ownable(msg.sender) {
        require(_rewardManager != address(0), "ProofOfUtility: Invalid reward manager");
        rewardManager = RewardManager(_rewardManager);
    }
    
    /**
     * @dev Record a usage event (called by dApp contracts)
     * @param user Address of the user
     * @param dAppContract Address of the dApp contract
     * @param dAppId ID of the dApp
     * @param actionType Type of action performed
     */
    function recordUsage(
        address user,
        address dAppContract,
        uint256 dAppId,
        string memory actionType
    ) public {
        require(user != address(0), "ProofOfUtility: Invalid user");
        require(dAppContract != address(0), "ProofOfUtility: Invalid dApp contract");
        
        UsageEvent memory event_ = UsageEvent({
            user: user,
            dAppContract: dAppContract,
            dAppId: dAppId,
            actionType: actionType,
            timestamp: block.timestamp
        });
        
        userEvents[user].push(event_);
        dAppEvents[dAppContract].push(event_);
        totalEvents++;
        
        emit UsageEventRecorded(user, dAppContract, dAppId, actionType, block.timestamp);
    }
    
    /**
     * @dev Record multiple usage events in batch (gas optimization)
     * @param users Array of user addresses
     * @param dAppContracts Array of dApp contract addresses
     * @param dAppIds Array of dApp IDs
     * @param actionTypes Array of action types
     */
    function recordUsageBatch(
        address[] memory users,
        address[] memory dAppContracts,
        uint256[] memory dAppIds,
        string[] memory actionTypes
    ) external {
        require(
            users.length == dAppContracts.length &&
            dAppContracts.length == dAppIds.length &&
            dAppIds.length == actionTypes.length,
            "ProofOfUtility: Array length mismatch"
        );
        
        for (uint256 i = 0; i < users.length; i++) {
            // Inline recordUsage logic for gas efficiency
            address user = users[i];
            address dAppContract = dAppContracts[i];
            uint256 dAppId = dAppIds[i];
            string memory actionType = actionTypes[i];
            
            require(user != address(0), "ProofOfUtility: Invalid user");
            require(dAppContract != address(0), "ProofOfUtility: Invalid dApp contract");
            
            UsageEvent memory event_ = UsageEvent({
                user: user,
                dAppContract: dAppContract,
                dAppId: dAppId,
                actionType: actionType,
                timestamp: block.timestamp
            });
            
            userEvents[user].push(event_);
            dAppEvents[dAppContract].push(event_);
            totalEvents++;
            
            emit UsageEventRecorded(user, dAppContract, dAppId, actionType, block.timestamp);
        }
    }
    
    /**
     * @dev Get user's usage events
     * @param user User address
     * @return Array of usage events
     */
    function getUserEvents(address user) external view returns (UsageEvent[] memory) {
        return userEvents[user];
    }
    
    /**
     * @dev Get dApp's usage events
     * @param dAppContract dApp contract address
     * @return Array of usage events
     */
    function getDAppEvents(address dAppContract) external view returns (UsageEvent[] memory) {
        return dAppEvents[dAppContract];
    }
    
    /**
     * @dev Get user's event count
     * @param user User address
     * @return Event count
     */
    function getUserEventCount(address user) external view returns (uint256) {
        return userEvents[user].length;
    }
    
    /**
     * @dev Record usage and distribute reward (called by dApp contracts)
     * @param user Address of the user
     * @param dAppContract Address of the dApp contract
     * @param dAppId ID of the dApp
     * @param actionType Type of action performed
     * @param actionValue Value of the action (for reward calculation)
     */
    function recordUsageAndReward(
        address user,
        address dAppContract,
        uint256 dAppId,
        string memory actionType,
        uint256 actionValue
    ) public {
        require(user != address(0), "ProofOfUtility: Invalid user");
        require(dAppContract != address(0), "ProofOfUtility: Invalid dApp contract");
        
        // Record usage event
        UsageEvent memory event_ = UsageEvent({
            user: user,
            dAppContract: dAppContract,
            dAppId: dAppId,
            actionType: actionType,
            timestamp: block.timestamp
        });
        
        userEvents[user].push(event_);
        dAppEvents[dAppContract].push(event_);
        totalEvents++;
        
        emit UsageEventRecorded(user, dAppContract, dAppId, actionType, block.timestamp);
        
        // Distribute reward if actionValue > 0
        if (actionValue > 0) {
            rewardManager.distributeReward(user, dAppContract, actionValue);
        }
    }
    
    /**
     * @dev Update reward manager (only owner)
     * @param _rewardManager New reward manager address
     */
    function setRewardManager(address _rewardManager) external onlyOwner {
        require(_rewardManager != address(0), "ProofOfUtility: Invalid reward manager");
        address oldManager = address(rewardManager);
        rewardManager = RewardManager(_rewardManager);
        emit RewardManagerUpdated(oldManager, _rewardManager);
    }
}

contracts/RevenueTreeManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title RevenueTreeManager
 * @dev Unified Revenue Tree per wallet per chain: referrer, volume, activation, upline snapshot, revenue distribution.
 * @notice One tree per wallet; upline immutable at activation; revenue to upline or same-level Genesis when inactive.
 */
contract RevenueTreeManager is Ownable, ReentrancyGuard {
    // --- Config (basis points 10000 = 100%) ---
    uint256 public constant BPS = 10000;
    uint256 public constant LEVELS = 5;
    uint256 public constant SECONDS_PER_DAY = 86400;
    uint256 public constant WINDOW_DAYS = 30;

    // Genesis wallets (L1..L5); used when level missing or inactive
    address[LEVELS] public genesisWallets;
    address public platformWallet; // remainder (platform share)

    // KREX path: hold >= krexThreshold and volumeLast30 >= krexMinVolume
    IERC20 public krexToken; // address(0) = disabled
    uint256 public krexThreshold;   // min balance (token units)
    uint256 public krexMinVolume;   // min volume in last 30 days (native wei)

    uint256 public activationThreshold;  // lifetime volume to activate (native wei, e.g. 100e18)
    uint256 public activityThreshold;    // volume in last 30 days to stay active (e.g. 1000e18)

    // Level share in basis points: L1=200, L2=500, L3=1000, L4=2000, L5=4500 => 8200; platform 1800
    uint256[LEVELS] public levelBps;

    mapping(address => bool) public authorizedCallers;

    // --- Per-user state ---
    mapping(address => address) public referrerOf;
    mapping(address => uint256) public lifetimeVolume;
    mapping(address => uint256) public activatedAt; // 0 = not activated
    mapping(address => address[LEVELS]) public upline; // 1-indexed: upline[user][0]=L1, [1]=L2, ...

    // volumeByDay[user][dayIndex] where dayIndex = timestamp / 86400
    mapping(address => mapping(uint256 => uint256)) public volumeByDay;

    // --- Events ---
    event ReferrerSet(address indexed user, address indexed referrer);
    event Activated(address indexed user, address l1, address l2, address l3, address l4, address l5);
    event RevenueDistributed(address indexed payer, uint256 amount, uint256 level, address indexed recipient, bool toGenesis);
    event AuthorizedCallerSet(address indexed caller, bool allowed);
    event ConfigUpdated();

    error InvalidAddress();
    error Unauthorized();
    error ReferrerAlreadySet();
    error TransferFailed();

    modifier onlyAuthorized() {
        if (!authorizedCallers[msg.sender]) revert Unauthorized();
        _;
    }

    /**
     * @param _genesisWallets Five Genesis addresses (L1..L5)
     * @param _platformWallet Receives platform share remainder
     * @param _krexToken KREX token or address(0) to disable KREX path
     * @param _activationThreshold Lifetime volume to activate (wei, e.g. 100e18)
     * @param _activityThreshold Volume in last 30 days for activity path (e.g. 1000e18)
     * @param _krexThreshold Min KREX balance for KREX path (token units, e.g. 10e6 * 1e18)
     * @param _krexMinVolume Min volume in last 30 days when using KREX path (e.g. 100e18)
     */
    constructor(
        address[LEVELS] memory _genesisWallets,
        address _platformWallet,
        address _krexToken,
        uint256 _activationThreshold,
        uint256 _activityThreshold,
        uint256 _krexThreshold,
        uint256 _krexMinVolume
    ) Ownable(msg.sender) {
        for (uint256 i = 0; i < LEVELS; i++) {
            if (_genesisWallets[i] == address(0)) revert InvalidAddress();
            genesisWallets[i] = _genesisWallets[i];
        }
        if (_platformWallet == address(0)) revert InvalidAddress();
        platformWallet = _platformWallet;

        krexToken = IERC20(_krexToken); // can be address(0)
        activationThreshold = _activationThreshold;
        activityThreshold = _activityThreshold;
        krexThreshold = _krexThreshold;
        krexMinVolume = _krexMinVolume;

        levelBps[0] = 200;  // L1 2%
        levelBps[1] = 500;  // L2 5%
        levelBps[2] = 1000; // L3 10%
        levelBps[3] = 2000; // L4 20%
        levelBps[4] = 4500; // L5 45%
        // remainder to platform
    }

    /**
     * @dev Set referrer once per user (first touch).
     */
    function setReferrer(address referrer) external {
        if (referrer == address(0) || referrer == msg.sender) revert InvalidAddress();
        if (referrerOf[msg.sender] != address(0)) revert ReferrerAlreadySet();
        referrerOf[msg.sender] = referrer;
        emit ReferrerSet(msg.sender, referrer);
    }

    /**
     * @dev Distribute msg.value to payer's upline (or Genesis for inactive/empty). Only authorized callers.
     */
    function distributeToUpline(address payer) external payable onlyAuthorized nonReentrant {
        if (payer == address(0) || msg.value == 0) return;

        uint256 dayIndex = block.timestamp / SECONDS_PER_DAY;
        lifetimeVolume[payer] += msg.value;
        volumeByDay[payer][dayIndex] += msg.value;

        // Activate if first time crossing threshold
        if (activatedAt[payer] == 0 && lifetimeVolume[payer] >= activationThreshold) {
            _activate(payer);
        }

        address[LEVELS] memory recipients = upline[payer];
        // If not yet activated, use genesis for all 5 levels
        if (activatedAt[payer] == 0) {
            for (uint256 i = 0; i < LEVELS; i++) {
                recipients[i] = genesisWallets[i];
            }
        }

        uint256 sent;
        for (uint256 i = 0; i < LEVELS; i++) {
            uint256 amount = (msg.value * levelBps[i]) / BPS;
            if (amount == 0) continue;
            address to = recipients[i];
            if (to == address(0)) to = genesisWallets[i];
            bool active = to != genesisWallets[i] && _isActive(to);
            if (!active) to = genesisWallets[i];
            (bool ok, ) = payable(to).call{value: amount}("");
            if (!ok) revert TransferFailed();
            sent += amount;
            emit RevenueDistributed(payer, amount, i + 1, to, to == genesisWallets[i]);
        }
        uint256 platformAmount = msg.value - sent;
        if (platformAmount > 0) {
            (bool ok, ) = payable(platformWallet).call{value: platformAmount}("");
            if (!ok) revert TransferFailed();
        }
    }

    function _activate(address user) internal {
        address ref = referrerOf[user];
        address[LEVELS] memory up;
        up[0] = user; // L1 = self
        if (ref != address(0)) {
            up[1] = ref;
            address r2 = referrerOf[ref];
            if (r2 != address(0)) {
                up[2] = r2;
                address r3 = referrerOf[r2];
                if (r3 != address(0)) {
                    up[3] = r3;
                    address r4 = referrerOf[r3];
                    if (r4 != address(0)) up[4] = r4;
                }
            }
        }
        for (uint256 i = 0; i < LEVELS; i++) {
            if (up[i] == address(0)) up[i] = genesisWallets[i];
            upline[user][i] = up[i];
        }
        activatedAt[user] = block.timestamp;
        emit Activated(user, up[0], up[1], up[2], up[3], up[4]);
    }

    function _isActive(address account) internal view returns (bool) {
        uint256 vol30 = getVolumeLast30Days(account);
        if (vol30 >= activityThreshold) return true;
        if (address(krexToken) == address(0)) return false;
        if (krexToken.balanceOf(account) < krexThreshold) return false;
        return vol30 >= krexMinVolume;
    }

    function getVolumeLast30Days(address user) public view returns (uint256) {
        uint256 today = block.timestamp / SECONDS_PER_DAY;
        uint256 sum = 0;
        for (uint256 d = 0; d < WINDOW_DAYS; d++) {
            uint256 day = today - d;
            sum += volumeByDay[user][day];
        }
        return sum;
    }

    function isActive(address user) external view returns (bool) {
        return _isActive(user);
    }

    function getUpline(address user) external view returns (address[LEVELS] memory) {
        address[LEVELS] memory out = upline[user];
        if (activatedAt[user] == 0) {
            for (uint256 i = 0; i < LEVELS; i++) {
                out[i] = genesisWallets[i];
            }
        }
        return out;
    }

    function getActivationStatus(address user) external view returns (bool activated, address[LEVELS] memory uplineSnapshot) {
        activated = activatedAt[user] != 0;
        uplineSnapshot = upline[user];
        if (!activated) {
            for (uint256 i = 0; i < LEVELS; i++) uplineSnapshot[i] = genesisWallets[i];
        }
        return (activated, uplineSnapshot);
    }

    function setAuthorizedCaller(address caller, bool allowed) external onlyOwner {
        authorizedCallers[caller] = allowed;
        emit AuthorizedCallerSet(caller, allowed);
    }

    function setGenesisWallets(address[LEVELS] calldata _genesisWallets) external onlyOwner {
        for (uint256 i = 0; i < LEVELS; i++) {
            if (_genesisWallets[i] != address(0)) genesisWallets[i] = _genesisWallets[i];
        }
        emit ConfigUpdated();
    }

    function setKrexToken(address _krexToken) external onlyOwner {
        krexToken = IERC20(_krexToken);
        emit ConfigUpdated();
    }

    function setPlatformWallet(address _platformWallet) external onlyOwner {
        if (_platformWallet == address(0)) revert InvalidAddress();
        platformWallet = _platformWallet;
        emit ConfigUpdated();
    }

    receive() external payable {}
}

contracts/RewardManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./GRIDToken.sol";
import "./ProofOfUtility.sol";

/**
 * @title RewardManager
 * @dev Distributes GRID only. FeeRouter uses distributeRewardDirect (95% user, 5% treasury).
 * @notice ProofOfUtility path (distributeReward) is deprecated for reward flow; use for analytics only.
 */
contract RewardManager is Ownable, ReentrancyGuard {
    uint256 public constant BPS = 10000;
    uint256 public constant GRID_TREASURY_BPS = 500; // 5%

    ProofOfUtility public proofOfUtility;
    GRIDToken public gridToken;
    address public gridTreasury;
    mapping(address => bool) public authorizedRewardCallers; // e.g. FeeRouter

    mapping(address => uint256) public rewardRates;

    event RewardDistributed(
        address indexed user,
        address indexed dAppContract,
        address indexed token,
        uint256 amount,
        string rewardType
    );
    event RewardDistributedDirect(address indexed user, uint256 amountToUser, uint256 amountToTreasury);
    event RewardRateUpdated(address indexed dAppContract, uint256 oldRate, uint256 newRate);
    event GridTreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);
    event AuthorizedRewardCallerSet(address indexed caller, bool allowed);
    
    modifier onlyAuthorizedRewardCaller() {
        require(authorizedRewardCallers[msg.sender], "RewardManager: Unauthorized");
        _;
    }

    constructor(address _proofOfUtility, address _gridToken) Ownable(msg.sender) {
        require(_proofOfUtility != address(0), "RewardManager: Invalid ProofOfUtility");
        require(_gridToken != address(0), "RewardManager: Invalid GRID token");
        proofOfUtility = ProofOfUtility(_proofOfUtility);
        gridToken = GRIDToken(_gridToken);
    }

    /**
     * @dev Direct GRID distribution: 95% to user, 5% to gridTreasury. Callable only by FeeRouter (or authorized).
     */
    function distributeRewardDirect(address user, uint256 amountWei) external nonReentrant onlyAuthorizedRewardCaller {
        require(user != address(0), "RewardManager: Invalid user");
        require(amountWei > 0, "RewardManager: Zero amount");
        require(gridTreasury != address(0), "RewardManager: Treasury not set");
        uint256 toUser = (amountWei * (BPS - GRID_TREASURY_BPS)) / BPS;
        uint256 toTreasury = amountWei - toUser;
        require(gridToken.balanceOf(address(this)) >= amountWei, "RewardManager: Insufficient GRID");
        require(gridToken.transfer(user, toUser), "RewardManager: Transfer to user failed");
        require(gridToken.transfer(gridTreasury, toTreasury), "RewardManager: Transfer to treasury failed");
        emit RewardDistributedDirect(user, toUser, toTreasury);
    }

    /**
     * @dev Legacy: distribute GRID for a usage event (ProofOfUtility only). Prefer FeeRouter -> distributeRewardDirect.
     */
    function distributeReward(
        address user,
        address dAppContract,
        uint256 actionValue
    ) public nonReentrant {
        require(user != address(0), "RewardManager: Invalid user");
        require(dAppContract != address(0), "RewardManager: Invalid dApp contract");
        require(msg.sender == address(proofOfUtility), "RewardManager: Only ProofOfUtility can call");
        uint256 rewardRate = rewardRates[dAppContract];
        if (rewardRate == 0) return;
        uint256 rewardAmount = (actionValue * rewardRate) / 10000;
        if (rewardAmount == 0) return;
        require(gridToken.balanceOf(address(this)) >= rewardAmount, "RewardManager: Insufficient GRID");
        require(gridToken.transfer(user, rewardAmount), "RewardManager: GRID transfer failed");
        emit RewardDistributed(user, dAppContract, address(gridToken), rewardAmount, "GRID");
    }

    /**
     * @dev Batch distribute GRID (ProofOfUtility only).
     */
    function distributeRewardsBatch(
        address[] memory users,
        address[] memory dAppContracts,
        uint256[] memory actionValues
    ) external nonReentrant {
        require(
            users.length == dAppContracts.length && dAppContracts.length == actionValues.length,
            "RewardManager: Array length mismatch"
        );
        require(msg.sender == address(proofOfUtility), "RewardManager: Only ProofOfUtility can call");
        for (uint256 i = 0; i < users.length; i++) {
            address user = users[i];
            address dAppContract = dAppContracts[i];
            uint256 actionValue = actionValues[i];
            if (user == address(0) || dAppContract == address(0)) continue;
            uint256 rewardRate = rewardRates[dAppContract];
            if (rewardRate == 0) continue;
            uint256 rewardAmount = (actionValue * rewardRate) / 10000;
            if (rewardAmount == 0) continue;
            if (gridToken.balanceOf(address(this)) < rewardAmount) continue;
            if (!gridToken.transfer(user, rewardAmount)) continue;
            emit RewardDistributed(user, dAppContract, address(gridToken), rewardAmount, "GRID");
        }
    }

    function setRewardRate(address dAppContract, uint256 rate) external onlyOwner {
        require(dAppContract != address(0), "RewardManager: Invalid dApp contract");
        require(rate <= 10000, "RewardManager: Rate cannot exceed 100%");
        uint256 oldRate = rewardRates[dAppContract];
        rewardRates[dAppContract] = rate;
        emit RewardRateUpdated(dAppContract, oldRate, rate);
    }

    function setGridTreasury(address _gridTreasury) external onlyOwner {
        require(_gridTreasury != address(0), "RewardManager: Invalid treasury");
        address old = gridTreasury;
        gridTreasury = _gridTreasury;
        emit GridTreasuryUpdated(old, _gridTreasury);
    }

    function setAuthorizedRewardCaller(address caller, bool allowed) external onlyOwner {
        require(caller != address(0), "RewardManager: Invalid caller");
        authorizedRewardCallers[caller] = allowed;
        emit AuthorizedRewardCallerSet(caller, allowed);
    }

    function setProofOfUtility(address _proofOfUtility) external onlyOwner {
        require(_proofOfUtility != address(0), "RewardManager: Invalid ProofOfUtility");
        proofOfUtility = ProofOfUtility(_proofOfUtility);
    }
}

contracts/SimplePayment.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./FeeCollector.sol";
import "./IFeeRouter.sol";

/**
 * @title SimplePayment
 * @dev Simple payment dApp with automatic fee collection
 * @notice First dApp demonstrating the fee collection pattern
 */
contract SimplePayment is Ownable, ReentrancyGuard {
    // Fee collector contract (used when feeRouter is not set)
    FeeCollector public feeCollector;
    // Optional: when set, fees go through FeeRouter for Revenue Tree distribution
    IFeeRouter public feeRouter;

    // Fee percentage (basis points, 10000 = 100%)
    uint256 public feePercentage;

    // Payment events
    event PaymentSent(
        address indexed from,
        address indexed to,
        uint256 amount,
        uint256 fee,
        uint256 timestamp
    );
    event FeeCollected(uint256 amount, uint256 timestamp);
    event FeeCollectorUpdated(address indexed oldCollector, address indexed newCollector);
    event FeeRouterUpdated(address indexed oldRouter, address indexed newRouter);
    event FeePercentageUpdated(uint256 oldPercentage, uint256 newPercentage);

    /**
     * @dev Constructor sets fee collector and fee percentage
     * @param _feeCollector Address of the FeeCollector contract
     * @param _feePercentage Fee percentage in basis points (e.g., 100 = 1%)
     */
    constructor(address _feeCollector, uint256 _feePercentage) Ownable(msg.sender) {
        require(_feeCollector != address(0), "SimplePayment: Invalid fee collector");
        require(_feePercentage <= 1000, "SimplePayment: Fee cannot exceed 10%");
        feeCollector = FeeCollector(_feeCollector);
        feePercentage = _feePercentage;
    }

    /**
     * @dev Send payment to a recipient with automatic fee deduction
     * @param _recipient Address to receive the payment
     * @notice Automatically deducts fee and sends to treasury
     */
    function sendPayment(address _recipient) external payable nonReentrant {
        require(_recipient != address(0), "SimplePayment: Invalid recipient");
        require(msg.value > 0, "SimplePayment: Amount must be greater than 0");

        uint256 fee = (msg.value * feePercentage) / 10000;
        uint256 paymentAmount = msg.value - fee;

        // Send fee: via FeeRouter (Revenue Tree + treasury + GRID + points) or FeeCollector only
        if (fee > 0) {
            if (address(feeRouter) != address(0)) {
                feeRouter.forwardFeeAndRevenueWithRewards{value: fee}(msg.sender, "dapp-payment", msg.value);
            } else {
                feeCollector.forwardFee{value: fee}();
            }
            emit FeeCollected(fee, block.timestamp);
        }

        // Send payment to recipient
        (bool success, ) = payable(_recipient).call{value: paymentAmount}("");
        require(success, "SimplePayment: Payment transfer failed");

        emit PaymentSent(msg.sender, _recipient, paymentAmount, fee, block.timestamp);
    }

    /**
     * @dev Update fee collector address
     * @param _feeCollector New fee collector address
     */
    function setFeeCollector(address _feeCollector) external onlyOwner {
        require(_feeCollector != address(0), "SimplePayment: Invalid fee collector");
        address oldCollector = address(feeCollector);
        feeCollector = FeeCollector(_feeCollector);
        emit FeeCollectorUpdated(oldCollector, _feeCollector);
    }

    /**
     * @dev Set FeeRouter for Revenue Tree; when set, fees use forwardFeeAndRevenue(payer) instead of FeeCollector.
     * @param _feeRouter Address of FeeRouter contract, or address(0) to use FeeCollector only
     */
    function setFeeRouter(address _feeRouter) external onlyOwner {
        address oldRouter = address(feeRouter);
        feeRouter = IFeeRouter(_feeRouter);
        emit FeeRouterUpdated(oldRouter, _feeRouter);
    }

    /**
     * @dev Update fee percentage
     * @param _feePercentage New fee percentage in basis points
     */
    function setFeePercentage(uint256 _feePercentage) external onlyOwner {
        require(_feePercentage <= 1000, "SimplePayment: Fee cannot exceed 10%");
        uint256 oldPercentage = feePercentage;
        feePercentage = _feePercentage;
        emit FeePercentageUpdated(oldPercentage, _feePercentage);
    }

    /**
     * @dev Calculate fee for a given amount
     * @param _amount Amount to calculate fee for
     * @return Fee amount
     */
    function calculateFee(uint256 _amount) external view returns (uint256) {
        return (_amount * feePercentage) / 10000;
    }

    /**
     * @dev Get payment amount after fee deduction
     * @param _amount Total amount
     * @return Payment amount after fee
     */
    function getPaymentAmount(uint256 _amount) external view returns (uint256) {
        uint256 fee = (_amount * feePercentage) / 10000;
        return _amount - fee;
    }
}

